const args=process.argv.slice(2),option=(flag,fallback)=>{const i=args.indexOf(flag);return i<0?fallback:args[i+1];};
const reviewDirectory=option('--review-directory','tests/step5e-gates/evidence');
const receiptPath=option('--receipt',null);assert(receiptPath,'Provide --receipt with actual candidate manifest');
const read=path=>{const full=resolve(path),rel=relative(process.cwd(),full);assert(rel&&!rel.startsWith('..')&&!rel.startsWith('/'),'Path escapes checkout');return readFileSync(full);};
const receipt=JSON.parse(read(receiptPath)),rows=parseCsv(read('ACCEPTANCE_STATUS.csv').toString()),original=JSON.parse(read('docs/specs/acceptance-source.json')),backlog=JSON.parse(read('docs/specs/backlog-source.json'));
assert.equal(rows.length,302);assert.equal(new Set(rows.map(row=>row.id)).size,302);assert.equal(backlog.length,86);
for(const item of original)for(const [key,value]of Object.entries(item))assert.equal(rows.find(row=>row.id===item.id)?.[key],value,`Original criterion changed:${item.id}`);
const sourceAtCommit=(commit,path)=>{assert(/^[a-f0-9]{40}$/.test(commit)&&!path.split('/').includes('..'));return execFileSync('git',['show',`${commit}:${path}`],{maxBuffer:64*1024*1024});};
const candidateErrors=verifyCurrentCandidate(receipt,{read,exists:existsSync,sourceAtCommit});
const browserPath=option('--browser-evidence',null),browserEntries=browserPath?JSON.parse(read(browserPath)):[],browsers=browserEntries.map(entry=>(entry.format==='ai-texas-step5e-native-gate-matrix'?verifyStep5EGateMatrix:entry.format==='ai-texas-step5e-native-sizing'?verifyStep5ESizing:entry.format==='ai-texas-step5e-native-mixed-statistics'?verifyStep5EMixedStatistics:entry.format==='ai-texas-step5e-native-exact-statistics'?verifyStep5EStatistics:verifyStep5EBrowser)(entry,receipt,{read,exists:existsSync,sourceAtCommit}));
